// export.js

// 1. 動態 Header 縮放邏輯
window.addEventListener('scroll', () => {
    const header = document.getElementById('main-header');
    if (!header) return;
    if (window.scrollY > 120) {
        header.classList.add('scrolled');
    } else if (window.scrollY < 20) {
        header.classList.remove('scrolled');
    }
});

// 2. 匯出報告功能
async function exportReport(type) {
    // 檢查依賴
    if (typeof html2canvas === 'undefined') {
        alert('正在載入繪圖套件，請稍後再試。');
        return;
    }
    if (type === 'pdf' && (!window.jspdf || !window.jspdf.jsPDF)) {
        alert('正在載入 PDF 套件，請稍後再試。');
        return;
    }

    const isPng = (type === 'png');
    const containerId = isPng ? 'export-card-container' : 'export-report-container';
    const container = document.getElementById(containerId);
    container.innerHTML = ''; // 清空先前內容
    container.style.display = 'block'; // 短暫顯示以供 html2canvas 擷取
    container.style.opacity = '1'; // html2canvas 必須要在元素有不透明度時才能擷取，否則會變成全黑
    container.style.position = 'absolute'; // 必須用 absolute，否則超過螢幕高度的部分會被 html2canvas 裁切掉
    container.style.top = '0';
    container.style.left = '0';
    container.style.zIndex = '-9999';
    container.style.pointerEvents = 'none';

    const currentAge = parseInt(document.getElementById('currentAge').value) || 26;
    let dataArr = (typeof isPureModeActive !== 'undefined' && isPureModeActive) ? simDataPure : simDataInv;
    
    if (isPng) {
        let teacher = dataArr[0];
        let oppIdx = 2; // Default semi
        if (document.getElementById('showSys') && document.getElementById('showSys').checked) oppIdx = 1;
        else if (document.getElementById('showSemi') && document.getElementById('showSemi').checked) oppIdx = 2;
        else if (document.getElementById('showStart') && document.getElementById('showStart').checked) oppIdx = 3;
        let opp = dataArr[oppIdx];

        let retAge = parseInt(document.getElementById('retireAge').value) || 65;
        let retIdx = retAge - currentAge;
        let endIdx = 90 - currentAge;
        if (retIdx < 0) retIdx = 0;
        if (endIdx < 0) endIdx = 0;

        let formatM = (num) => '$ ' + Math.round(num).toLocaleString();

        container.innerHTML = `
            <style>
                .bc-wrap { width: 1080px; height: 1350px; background-color: #ffffff; background-image: radial-gradient(circle at top right, rgba(14, 165, 233, 0.05), transparent 40%), radial-gradient(circle at bottom left, rgba(139, 92, 246, 0.05), transparent 40%); color: #1e293b; font-family: -apple-system, BlinkMacSystemFont, "SF Pro Text", sans-serif; padding: 50px 60px; box-sizing: border-box; position: relative; overflow: hidden; border: 4px solid #f1f5f9; }
                .bc-title { text-align: center; margin-bottom: 25px; }
                .bc-title h1 { font-size: 56px; font-weight: 900; margin: 0; color: #0f172a; letter-spacing: 2px; }
                .bc-title p { font-size: 24px; color: #64748b; margin-top: 10px; font-weight: 600; }
                .bc-vs { display: flex; justify-content: space-between; gap: 30px; position: relative; z-index: 10; }
                
                .bc-panel { flex: 1; background: #ffffff; border-radius: 32px; padding: 35px 30px; border: 2px solid #e2e8f0; box-shadow: 0 15px 35px rgba(0,0,0,0.05); display: flex; flex-direction: column; align-items: center; }
                .bc-teacher { border-top: 8px solid #0ea5e9; }
                .bc-tech { border-top: 8px solid #f59e0b; }
                
                .bc-avatar { width: 120px; height: 120px; border-radius: 50%; object-fit: cover; margin-bottom: 15px; border: 4px solid #fff; box-shadow: 0 8px 20px rgba(0,0,0,0.1); background-color: #f8fafc; }
                .bc-role { font-size: 38px; font-weight: 900; text-align: center; margin-bottom: 25px; letter-spacing: 1px; }
                .bc-teacher .bc-role { color: #0284c7; }
                .bc-tech .bc-role { color: #d97706; }
                
                .bc-metric-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 15px; width: 100%; margin-bottom: 20px; }
                .bc-metric { background: #f8fafc; padding: 15px; border-radius: 16px; text-align: center; border: 1px solid #f1f5f9; }
                .bc-metric.full { grid-column: span 2; background: #f1f5f9; }
                .bc-label { font-size: 15px; color: #64748b; margin-bottom: 8px; font-weight: 700; text-transform: uppercase; letter-spacing: 1px; }
                .bc-value { font-size: 32px; font-weight: 800; color: #0f172a; }
                
                .bc-div { height: 2px; width: 100%; background: linear-gradient(to right, transparent, #e2e8f0, transparent); margin: 20px 0; }
                
                .bc-ult { text-align: center; margin-top: 10px; width: 100%; background: #f8fafc; padding: 15px; border-radius: 20px; border: 1px solid #e2e8f0; }
                .bc-ult.highlight { background: #fffbeb; border-color: #fef3c7; }
                .bc-teacher .bc-ult.highlight { background: #f0f9ff; border-color: #e0f2fe; }
                
                .bc-ult-label { font-size: 18px; color: #475569; margin-bottom: 8px; font-weight: 800; letter-spacing: 1px; }
                .bc-ult-val { font-size: 52px; font-weight: 900; line-height: 1.1; }
                .bc-teacher .bc-ult-val { color: #0369a1; }
                .bc-tech .bc-ult-val { color: #b45309; }
                
                .bc-badge { position: absolute; top: 40%; left: 50%; transform: translate(-50%, -50%); width: 70px; height: 70px; background: #ffffff; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-size: 24px; font-weight: 900; border: 4px solid #f1f5f9; box-shadow: 0 10px 25px rgba(0,0,0,0.1); z-index: 20; color: #94a3b8; }
                .bc-chart { margin-top: 25px; height: 260px; background: #ffffff; border: 2px solid #e2e8f0; border-radius: 24px; display: flex; align-items: center; justify-content: center; overflow: hidden; padding: 15px; box-shadow: 0 15px 35px rgba(0,0,0,0.05); }
                .bc-footer { position: absolute; bottom: 25px; left: 0; width: 100%; text-align: center; font-size: 20px; color: #94a3b8; font-weight: 700; letter-spacing: 3px; }
            </style>
            <div class="bc-wrap">
                <div class="bc-title">
                    <h1>Teach or Not</h1>
                    <p>職涯財富精算 | ${currentAge}歲起跑 | 投資報酬率 ${document.getElementById('roi').value}%</p>
                </div>
                <div class="bc-vs">
                    <div class="bc-panel bc-teacher">
                        <img src="data:image/png;base64," class="bc-avatar" onerror="this.style.display='none'">
                        <div class="bc-role">${teacher.title}</div>
                        
                        <div class="bc-metric-grid">
                            <div class="bc-metric full">
                                <div class="bc-label">目前月收入</div>
                                <div class="bc-value" style="color: #0284c7;">${formatM(teacher.mGross[0])}</div>
                            </div>
                            <div class="bc-metric">
                                <div class="bc-label">每月可支配</div>
                                <div class="bc-value">${formatM(teacher.mExp[0] || teacher.mGross[0])}</div>
                            </div>
                            <div class="bc-metric">
                                <div class="bc-label">每月投資</div>
                                <div class="bc-value">${formatM(teacher.mInv[0])}</div>
                            </div>
                        </div>

                        <div class="bc-div"></div>
                        
                        <div class="bc-ult">
                            <div class="bc-ult-label">${retAge}歲累積總資產</div>
                            <div class="bc-value" style="font-size: 40px; color: #334155;">${formatM((teacher.wT[retIdx]||0) + (teacher.wT_pool[retIdx]||0))}</div>
                        </div>
                        
                        <div class="bc-ult highlight">
                            <div class="bc-ult-label">90歲終極身價</div>
                            <div class="bc-ult-val">${formatM((teacher.wT[endIdx]||0) + (teacher.wT_pool[endIdx]||0))}</div>
                        </div>
                    </div>
                    
                    <div class="bc-badge">VS</div>
                    
                    <div class="bc-panel bc-tech">
                        <img src="data:image/png;base64," class="bc-avatar" onerror="this.style.display='none'">
                        <div class="bc-role">${opp.title}</div>
                        
                        <div class="bc-metric-grid">
                            <div class="bc-metric full">
                                <div class="bc-label">目前月收入</div>
                                <div class="bc-value" style="color: #d97706;">${formatM(opp.mGross[0])}</div>
                            </div>
                            <div class="bc-metric">
                                <div class="bc-label">每月可支配</div>
                                <div class="bc-value">${formatM(opp.mExp[0] || opp.mGross[0])}</div>
                            </div>
                            <div class="bc-metric">
                                <div class="bc-label">每月投資</div>
                                <div class="bc-value">${formatM(opp.mInv[0])}</div>
                            </div>
                        </div>

                        <div class="bc-div"></div>
                        
                        <div class="bc-ult">
                            <div class="bc-ult-label">退休時累積總資產</div>
                            <div class="bc-value" style="font-size: 40px; color: #334155;">${formatM((opp.wT[retIdx]||0) + (opp.wT_pool[retIdx]||0))}</div>
                        </div>
                        
                        <div class="bc-ult highlight">
                            <div class="bc-ult-label">90歲終極身價</div>
                            <div class="bc-ult-val">${formatM((opp.wT[endIdx]||0) + (opp.wT_pool[endIdx]||0))}</div>
                        </div>
                    </div>
                </div>
                <div class="bc-chart" id="bc-chart-target"></div>
                <div class="bc-footer">TEACH OR NOT - SYSTEM</div>
            </div>
        `;

        const sourceCanvas = document.getElementById('cumulativeChart');
        if (sourceCanvas) {
            const targetContainer = document.getElementById('bc-chart-target');
            const imgUrl = sourceCanvas.toDataURL('image/png');
            const img = document.createElement('img');
            img.src = imgUrl;
            img.style.width = '100%';
            img.style.height = '100%';
            img.style.objectFit = 'contain';
            targetContainer.appendChild(img);
        }

    } else {
        // 生成 PDF 的 A4 排版內容
        container.innerHTML = `
            <div style="font-family: '-apple-system', 'BlinkMacSystemFont', 'SF Pro Text', sans-serif; padding: 20px;">
                <div style="text-align: center; margin-bottom: 30px;">
                    <h1 style="color: #06b6d4; margin: 0; font-size: 28px;">Teach or Not 職涯財富精算報告</h1>
                    <p style="color: #475569; margin-top: 8px; font-size: 14px;">目前年齡: ${currentAge} 歲 | 報告產出時間: ${new Date().toLocaleDateString()}</p>
                </div>
                
                <h2 style="color: #0f172a; border-bottom: 2px solid #06b6d4; padding-bottom: 8px; font-size: 18px;">目前狀態與參數</h2>
                <div style="display: flex; gap: 20px; margin-bottom: 30px; font-size: 13px;">
                    <div style="flex: 1; background: #f1f5f9; padding: 15px; border-radius: 8px; border: 1px solid #e2e8f0;">
                        <h3 style="margin-top: 0; color: #334155; font-size: 15px;">環境與分配</h3>
                        <p style="margin: 5px 0;"><strong>投資報酬率:</strong> ${document.getElementById('roi').value}%</p>
                        <p style="margin: 5px 0;"><strong>退休金投報率:</strong> ${document.getElementById('pensionRoi').value}%</p>
                        <p style="margin: 5px 0;"><strong>已有投資:</strong> ${parseInt(document.getElementById('initInvest').value).toLocaleString()} 元</p>
                        <p style="margin: 5px 0;"><strong>已有存款:</strong> ${parseInt(document.getElementById('initCash').value).toLocaleString()} 元</p>
                    </div>
                    <div style="flex: 1; background: #f1f5f9; padding: 15px; border-radius: 8px; border: 1px solid #e2e8f0;">
                        <h3 style="margin-top: 0; color: #334155; font-size: 15px;">公教設定</h3>
                        <p style="margin: 5px 0;"><strong>最高學歷:</strong> ${document.getElementById('teacherDegree').options[document.getElementById('teacherDegree').selectedIndex].text}</p>
                        <p style="margin: 5px 0;"><strong>起敘薪點:</strong> ${document.getElementById('startPoint').value}</p>
                        <p style="margin: 5px 0;"><strong>教師身份:</strong> ${document.getElementById('teacherType').options[document.getElementById('teacherType').selectedIndex].text}</p>
                    </div>
                </div>

                <h2 style="color: #0f172a; border-bottom: 2px solid #f59e0b; padding-bottom: 8px; font-size: 18px;">${currentAge} 歲 - 財務結構明細表 (教師)</h2>
                <div id="report-tables" style="margin-bottom: 30px; font-size: 13px;">
                    <!-- Tables will be injected here -->
                </div>

                <h2 style="color: #0f172a; border-bottom: 2px solid #8b5cf6; padding-bottom: 8px; font-size: 18px;">生命週期曲線圖</h2>
                <div id="report-chart-cumulative" style="width: 100%; height: auto; text-align: center;"></div>
            </div>
        `;

        let teacherData = null;
        if (dataArr && dataArr[0]) {
            let p = dataArr[0];
            let idx = 0; // The first year logic matches idx=0 in the loop
            if (idx >= 0 && idx < p.aGross.length) {
                teacherData = {
                    monthlyGross: p.mGross[idx],
                    annualGross: p.aGross[idx],
                    tax: p.aTax[idx].tax,
                    laborInsY: p.aLabor[idx],
                    healthInsY: p.aHealth[idx],
                    expenseM: p.mExp[idx],
                    expenseY: p.aExp[idx],
                    investM: p.mInv[idx],
                    investY: p.aInv[idx],
                    saveM: p.mSav[idx],
                    saveY: p.aSav[idx],
                    cumNetAssets: p.wT[idx],
                    pensionPool: p.wT_pool[idx]
                };
            }
        }
        
        if (teacherData) {
            const tableHtml = `
                <table style="width: 100%; border-collapse: collapse; text-align: left;">
                    <thead>
                        <tr style="background: #f1f1f1; color: #0f172a;">
                            <th style="padding: 10px; border: 1px solid #ddd;">項目</th>
                            <th style="padding: 10px; border: 1px solid #ddd; text-align: right;">每月金額</th>
                            <th style="padding: 10px; border: 1px solid #ddd; text-align: right;">年度總額</th>
                        </tr>
                    </thead>
                    <tbody>
                        <tr>
                            <td style="padding: 10px; border: 1px solid #ddd;">應發薪資 (本俸+加給)</td>
                            <td style="padding: 10px; border: 1px solid #ddd; text-align: right;">${Math.round(teacherData.monthlyGross).toLocaleString()}</td>
                            <td style="padding: 10px; border: 1px solid #ddd; text-align: right;">${Math.round(teacherData.annualGross).toLocaleString()}</td>
                        </tr>
                        <tr>
                            <td style="padding: 10px; border: 1px solid #ddd; color: #ef4444;">稅金與保費支出</td>
                            <td style="padding: 10px; border: 1px solid #ddd; text-align: right; color: #ef4444;">-${Math.round((teacherData.tax + teacherData.laborInsY + teacherData.healthInsY)/12).toLocaleString()}</td>
                            <td style="padding: 10px; border: 1px solid #ddd; text-align: right; color: #ef4444;">-${Math.round(teacherData.tax + teacherData.laborInsY + teacherData.healthInsY).toLocaleString()}</td>
                        </tr>
                        <tr>
                            <td style="padding: 10px; border: 1px solid #ddd; color: #f59e0b;">生活費支出</td>
                            <td style="padding: 10px; border: 1px solid #ddd; text-align: right; color: #f59e0b;">-${Math.round(teacherData.expenseM).toLocaleString()}</td>
                            <td style="padding: 10px; border: 1px solid #ddd; text-align: right; color: #f59e0b;">-${Math.round(teacherData.expenseY).toLocaleString()}</td>
                        </tr>
                        <tr>
                            <td style="padding: 10px; border: 1px solid #ddd; color: #10b981;">投資分配</td>
                            <td style="padding: 10px; border: 1px solid #ddd; text-align: right; color: #10b981;">${Math.round(teacherData.investM).toLocaleString()}</td>
                            <td style="padding: 10px; border: 1px solid #ddd; text-align: right; color: #10b981;">${Math.round(teacherData.investY).toLocaleString()}</td>
                        </tr>
                        <tr>
                            <td style="padding: 10px; border: 1px solid #ddd; color: #0ea5e9;">儲蓄分配</td>
                            <td style="padding: 10px; border: 1px solid #ddd; text-align: right; color: #0ea5e9;">${Math.round(teacherData.saveM).toLocaleString()}</td>
                            <td style="padding: 10px; border: 1px solid #ddd; text-align: right; color: #0ea5e9;">${Math.round(teacherData.saveY).toLocaleString()}</td>
                        </tr>
                        <tr style="background: rgba(6, 182, 212, 0.05); font-weight: bold; font-size: 14px;">
                            <td style="padding: 10px; border: 1px solid #ddd;">累積可動用總資產</td>
                            <td style="padding: 10px; border: 1px solid #ddd; text-align: right; color: #06b6d4;" colspan="2">${Math.round(teacherData.cumNetAssets).toLocaleString()} 元</td>
                        </tr>
                        <tr style="background: rgba(139, 92, 246, 0.05); font-weight: bold; font-size: 14px;">
                            <td style="padding: 10px; border: 1px solid #ddd;">退休資金池 (含雇主與政府提撥)</td>
                            <td style="padding: 10px; border: 1px solid #ddd; text-align: right; color: #8b5cf6;" colspan="2">${Math.round(teacherData.pensionPool).toLocaleString()} 元</td>
                        </tr>
                    </tbody>
                </table>
            `;
            document.getElementById('report-tables').innerHTML = tableHtml;
        } else {
            document.getElementById('report-tables').innerHTML = '<p style="color:red; text-align:center; padding: 20px;">資料生成失敗。請先點擊「執行精算更新」後，再嘗試匯出。</p>';
        }

        const sourceCanvas = document.getElementById('cumulativeChart');
        if (sourceCanvas) {
            const targetContainer = document.getElementById('report-chart-cumulative');
            const imgUrl = sourceCanvas.toDataURL('image/png');
            const img = document.createElement('img');
            img.src = imgUrl;
            img.style.maxWidth = '100%';
            img.style.height = 'auto';
            img.style.borderRadius = '8px';
            img.style.border = '1px solid #eee';
            img.style.boxShadow = '0 4px 10px rgba(0,0,0,0.05)';
            targetContainer.appendChild(img);
        }
    }

    // 顯示載入中提示
    const btnText = type === 'png' ? '圖片生成中...' : 'PDF 生成中...';
    const originalBtn = document.activeElement;
    if (originalBtn && originalBtn.tagName === 'BUTTON') {
        originalBtn.dataset.originalText = originalBtn.innerText;
        originalBtn.innerText = btnText;
        originalBtn.disabled = true;
    }

    // 等待渲染完成
    await new Promise(r => setTimeout(r, 100));

    try {
        const canvas = await html2canvas(container, {
            scale: 2,
            useCORS: true,
            backgroundColor: isPng ? '#0b1120' : '#ffffff',
            scrollX: 0,
            scrollY: 0,
            x: 0,
            y: 0,
            windowWidth: container.scrollWidth,
            windowHeight: container.scrollHeight
        });

        if (type === 'png') {
            const imgData = canvas.toDataURL('image/png');
            const previewImg = document.getElementById('preview-image');
            const downloadLink = document.getElementById('download-link');
            const modal = document.getElementById('preview-modal');
            
            if (previewImg && downloadLink && modal) {
                previewImg.src = imgData;
                downloadLink.href = imgData;
                downloadLink.download = `TeachOrNot_BattleCard_${currentAge}歲.png`;
                modal.style.display = 'flex';
            } else {
                // Fallback
                const link = document.createElement('a');
                link.download = `TeachOrNot_BattleCard_${currentAge}歲.png`;
                link.href = imgData;
                link.click();
            }
        } else if (type === 'pdf') {
            const imgData = canvas.toDataURL('image/jpeg', 1.0);
            const { jsPDF } = window.jspdf;
            
            const pdf = new jsPDF('p', 'mm', 'a4');
            const pdfWidth = pdf.internal.pageSize.getWidth();
            let pdfHeight = (canvas.height * pdfWidth) / canvas.width;
            const pageHeight = pdf.internal.pageSize.getHeight();
            
            let finalWidth = pdfWidth;
            let finalHeight = pdfHeight;
            let startX = 0;
            let startY = 0;
            
            if (pdfHeight > pageHeight) {
                // 如果內容超過一頁高度，將其等比例縮放以適合一頁
                const ratio = pageHeight / pdfHeight;
                finalHeight = pageHeight;
                finalWidth = pdfWidth * ratio;
                startX = (pdfWidth - finalWidth) / 2;
            }
            
            pdf.addImage(imgData, 'JPEG', startX, startY, finalWidth, finalHeight);
            pdf.save(`TeachOrNot_Report_${currentAge}歲.pdf`);
        }
    } catch (err) {
        console.error('Export failed:', err);
        alert('匯出時發生錯誤，請稍後再試。');
    } finally {
        container.style.display = 'none';
        container.style.opacity = '0';
        container.style.position = 'fixed';
        if (originalBtn && originalBtn.tagName === 'BUTTON') {
            originalBtn.innerText = originalBtn.dataset.originalText;
            originalBtn.disabled = false;
        }
    }
}

window.isSimulationRun = false;
function exportReportSafe(type) {
    if (!window.isSimulationRun) {
        alert('請先點擊「執行精算更新」產生資料後再匯出！');
        return;
    }
    exportReport(type);
}
